 art={'kind': 'bars', 'label': 'Nvidia quarterly revenue, $ billion', 'unit': '$B', 'items': [('Q3 FY26', 57.0), ('Q2 FY27', 96.2), ('Q3 FY27', 115.8), ('Q4 outlook', 130.0)]},
